130	.arch-diagram svg { width: 100%; height: auto; display: block; }
131	table.info {
132	  width: 100%; border-collapse: collapse; background: var(--card);
133	  border: 1px solid var(--line); border-radius: var(--radius); overflow: hidden;
134	  font-size: 14.5px;
135	}
136	table.info th, table.info td {
137	  padding: 12px 16px; text-align: left; border-bottom: 1px solid var(--line); vertical-align: top;
138	}
139	table.info th { background: #f0f4fa; font-size: 13.5px; white-space: nowrap; }
140	table.info tr:last-child td { border-bottom: none; }
141	table.info td.wide { min-width: 180px; }
