143	  font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
144	  font-size: 0.9em; background: #eef1f7; border-radius: 4px; padding: 1px 6px; color: #24446e;
145	}
146	
147	/* ---------- demo / radar ---------- */
