186	@media (max-width: 700px) {
187	  .blind-table-wrap { display: none; }
188	  .blind-cards { display: block; }
189	}
190	
191	/* term list inside detail */
192	.term-list { margin: 6px 0 0; padding: 0; list-style: none; font-size: 13.5px; }
193	.term-list li { padding: 7px 0; border-bottom: 1px dashed #e3e8f0; }
194	.term-list li:last-child { border-bottom: none; }
195	.term-line { display: flex; align-items: baseline; gap: 8px; flex-wrap: wrap; }
196	.term-name { font-weight: 600; }
197	.term-alias { color: var(--ink-faint); font-size: 12.5px; }
198	.term-found { color: var(--ok); font-weight: 600; white-space: nowrap; }
199	.term-miss { color: var(--bad); font-weight: 600; white-space: nowrap; }
200	.term-chunks { margin-top: 4px; color: var(--ink-soft); font-size: 12.5px; }
201	.term-chunks div { padding: 1px 0; }
202	
203	/* question content with expand */
204	.q-item { padding: 8px 0; border-bottom: 1px dashed #e3e8f0; font-size: 13.5px; }
205	.q-item:last-child { border-bottom: none; }
206	.q-item .q-line { color: var(--ink-soft); }
207	.q-item .q-content { margin-top: 4px; color: var(--ink-soft); }
208	.q-item .q-toggle {
209	  background: none; border: none; color: var(--primary); font-size: 12.5px;
210	  padding: 0; cursor: pointer; text-decoration: underline;
211	}
212	.detail-box { padding: 18px 18px 20px; background: #fafbfd; }
213	.detail-box h4 { margin: 0 0 10px; font-size: 14px; color: var(--ink-soft); }
214	.evidence {
215	  background: #fff; border: 1px solid var(--line); border-left: 3px solid var(--primary);
216	  border-radius: 8px; padding: 12px 16px; font-size: 14px;
217	}
218	.evidence .ev-meta { font-size: 12.5px; color: var(--ink-faint); margin-top: 8px; }
219	.evidence .ev-content { color: var(--ink-soft); font-size: 13.5px; }
220	.q-list { margin: 14px 0 0; padding: 0; list-style: none; font-size: 13.5px; color: var(--ink-soft); }
221	.q-list li { padding: 3px 0; }
222	.reason-text { font-size: 13.5px; color: var(--ink-soft); margin: 12px 0 0; }
223	.muted { color: var(--ink-faint); }
224	
225	.badge {
226	  display: inline-block; padding: 2px 10px; border-radius: 999px; font-size: 12.5px; font-weight: 600; white-space: nowrap;
227	}
228	.badge.covered { background: var(--ok-soft); color: var(--ok); }
229	.badge.thin { background: var(--warn-soft); color: var(--warn); }
230	.badge.missing { background: var(--bad-soft); color: var(--bad); }
231	.badge.unknown { background: #eef1f7; color: var(--ink-faint); }
232	
233	/* ---------- run locally ---------- */
234	.cmd-block {
235	  background: #101a2e; color: #d5e2f7; border-radius: var(--radius);
236	  padding: 18px 22px; font-family: ui-monospace, SFMono-Regular, Menlo, monospace;
237	  font-size: 14px; line-height: 2; overflow-x: auto; margin: 18px 0 10px;
238	}
239	.cmd-block .cmt { color: #6f81a3; }
240	.cmd-links { font-size: 14px; }
241	.table-scroll { overflow-x: auto; -webkit-overflow-scrolling: touch; }
242	.cmd-links a { color: var(--primary); text-decoration: none; margin-right: 18px; }
243	.cmd-links a:hover { text-decoration: underline; }
244	
245	/* ---------- video ---------- */
246	.video-box {
247	  background: var(--card); border: 1px solid var(--line); border-radius: var(--radius);
248	  overflow: hidden;
249	}
250	.video-box video { display: block; width: 100%; max-height: 560px; background: #000; }
251	.video-pending {
252	  padding: 90px 20px; text-align: center; color: var(--ink-faint);
253	}
254	.video-pending .film { font-size: 40px; margin-bottom: 10px; }
255	
256	/* ---------- sessions ---------- */
257	.sessions-table-wrap { overflow-x: auto; }
258	table.sessions { width: 100%; border-collapse: collapse; background: var(--card); border: 1px solid var(--line); border-radius: var(--radius); overflow: hidden; font-size: 14px; }
259	table.sessions { table-layout: fixed; }
260	table.sessions th, table.sessions td { padding: 10px 14px; text-align: left; border-bottom: 1px solid var(--line); white-space: nowrap; }
261	table.sessions th { background: #f0f4fa; font-size: 13px; }
262	table.sessions td.title-cell { white-space: normal; overflow-wrap: anywhere; }
263	table.sessions td.num, table.sessions th.num { text-align: right; white-space: nowrap; }
264	table.sessions tr.total td { background: #f0f4fa; font-weight: 700; border-bottom: none; }
265	table.sessions td.title-cell { min-width: 260px; }
266	.model-tag { white-space: nowrap; }
267	.model-tag.glm { color: #9333ea; font-weight: 600; }
268	
269	.split-note {
270	  display: grid; grid-template-columns: 1fr 1fr; gap: 18px; margin: 26px 0 18px;
271	}
272	.split-card { background: var(--card); border: 1px solid var(--line); border-radius: var(--radius); padding: 20px 22px; }
273	.split-card h3 { margin: 0 0 8px; font-size: 16px; }
274	.split-card ul { margin: 0; padding-left: 18px; font-size: 14px; color: var(--ink-soft); }
275	.split-card ul li { margin: 4px 0; }
276	
277	/* ---------- usage ---------- */
278	.usage-card {
279	  background: var(--card); border: 1px dashed #b9c3d4; border-radius: var(--radius);
280	  padding: 48px 30px; text-align: center; color: var(--ink-soft);
281	}
282	.usage-card .icon { font-size: 34px; margin-bottom: 10px; }
283	.usage-stats { display: grid; grid-template-columns: repeat(4, 1fr); gap: 16px; margin-bottom: 20px; }
284	.stat { background: var(--card); border: 1px solid var(--line); border-radius: var(--radius); padding: 18px; text-align: center; }
285	.stat .v { font-size: 26px; font-weight: 700; color: var(--ink); }
286	.stat .k { font-size: 13px; color: var(--ink-faint); margin-top: 4px; }
287	.usage-src { font-size: 13px; color: var(--ink-faint); }
288	
289	.usage-block {
290	  background: var(--card); border: 1px solid var(--line); border-radius: var(--radius);
291	  padding: 22px 24px; margin-bottom: 18px;
292	}
293	.usage-block h3 { margin: 0 0 14px; font-size: 16px; }
294	.usage-block .usage-stats { margin-bottom: 6px; }
295	.feedback-list { margin: 0; padding: 0; list-style: none; }
296	.feedback-list li {
297	  border-left: 3px solid var(--primary); background: #f7f9fd;
298	  border-radius: 0 8px 8px 0; padding: 12px 16px; margin-bottom: 10px;
299	  font-size: 14.5px; color: var(--ink-soft); font-style: normal;
300	}
301	.feedback-list li:last-child { margin-bottom: 0; }
302	
303	/* ---------- footer ---------- */
304	footer {
305	  background: #101a2e; color: #aab8d0; padding: 44px 0 36px; font-size: 13.5px;
306	}
307	footer .cols { display: grid; grid-template-columns: 1.4fr 1fr 1fr; gap: 30px; }
308	footer h4 { color: #fff; font-size: 14px; margin: 0 0 10px; }
309	footer a { color: #8fb1f5; text-decoration: none; }
310	footer a:hover { text-decoration: underline; }
311	footer p { margin: 4px 0; }
312	footer .copy { border-top: 1px solid #26324d; margin-top: 28px; padding-top: 18px; color: #7787a5; font-size: 12.5px; }
313	
314	/* ---------- responsive ---------- */
315	@media (max-width: 900px) {
316	  .hero-grid, .radar-layout, .feature, .split-note { grid-template-columns: 1fr; }
317	  .feature .shot { order: 2; }
318	  .pain-grid { grid-template-columns: 1fr; }
319	  .usage-stats { grid-template-columns: repeat(2, 1fr); }
320	  footer .cols { grid-template-columns: 1fr; gap: 20px; }
321	  nav.topbar .links { display: none; }
322	}
323	@media (max-width: 480px) {
324	  .hero h1 { font-size: 30px; }
325	  section { padding: 40px 0; }
326	  #radar-chart { height: 340px; }
327	}
