file.content:
:root {
  --ink: #1a2333;
  --ink-soft: #4a5568;
  --ink-faint: #8a94a6;
  --bg: #f6f8fb;
  --card: #ffffff;
  --line: #e3e8f0;
  --primary: #2456d6;
  --primary-dark: #1a3fa0;
  --primary-soft: #eaf0fd;
  --ok: #178a50;
  --ok-soft: #e6f6ee;
  --warn: #b8860b;
  --warn-soft: #fdf5e0;
  --bad: #c0392b;
  --bad-soft: #fdeceb;
  --radius: 12px;
  --shadow: 0 1px 3px rgba(26, 35, 51, 0.08), 0 4px 14px rgba(26, 35, 51, 0.05);
}

* { box-sizing: border-box; }

[hidden] { display: none !important; }

html { scroll-behavior: smooth; }

body {
  margin: 0;
  font-family: -apple-system, BlinkMacSystemFont, "PingFang SC", "Hiragino Sans GB",
    "Microsoft YaHei", "Noto Sans CJK SC", "Segoe UI", sans-serif;
  color: var(--ink);
  background: var(--bg);
  line-height: 1.7;
}

.wrap { max-width: 1060px; margin: 0 auto; padding: 0 20px; }

section { padding: 56px 0; }
section.alt { background: var(--card); border-top: 1px solid var(--line); border-bottom: 1px solid var(--line); }

h2.sec-title {
  font-size: 26px;
  margin: 0 0 6px;
  letter-spacing: 0.5px;
}
p.sec-sub { color: var(--ink-soft); margin: 0 0 28px; max-width: 720px; }

/* ---------- top nav ---------- */
nav.topbar {
  position: sticky; top: 0; z-index: 50;
  background: rgba(255, 255, 255, 0.92);
  backdrop-filter: blur(8px);
  border-bottom: 1px solid var(--line);
}
nav.topbar .wrap {
  display: flex; align-items: center; gap: 22px;
  height: 54px;
}
.brand { font-weight: 700; font-size: 17px; color: var(--ink); text-decoration: none; white-space: nowrap; }
.brand .radar-dot { color: var(--primary); }
nav.topbar .links { display: flex; gap: 18px; margin-left: auto; }
nav.topbar a.nav-link {
  color: var(--ink-soft); text-decoration: none; font-size: 14px; white-space: nowrap;
}
nav.topbar a.nav-link:hover { color: var(--primary); }

/* ---------- hero ---------- */
header.hero { padding: 84px 0 72px; }
.hero-grid { display: grid; grid-template-columns: 1.25fr 1fr; gap: 48px; align-items: center; }
.hero h1 { font-size: 40px; line-height: 1.25; margin: 0 0 6px; }
.hero h1 .en { display: block; font-size: 18px; font-weight: 500; color: var(--ink-faint); letter-spacing: 3px; margin-top: 4px; }
.hero p.tagline { font-size: 18px; color: var(--ink-soft); margin: 14px 0 30px; max-width: 560px; }
.hero .btns { display: flex; gap: 14px; flex-wrap: wrap; }
a.btn {
  display: inline-block; padding: 11px 26px; border-radius: 999px;
  font-size: 15px; text-decoration: none; font-weight: 600;
  transition: background 0.15s, transform 0.1s;
}
a.btn.primary { background: var(--primary); color: #fff; }
a.btn.primary:hover { background: var(--primary-dark); }
a.btn.ghost { border: 1.5px solid var(--primary); color: var(--primary); }
a.btn.ghost:hover { background: var(--primary-soft); }
.hero-visual {
  background: var(--card); border: 1px solid var(--line); border-radius: var(--radius);
  box-shadow: var(--shadow); padding: 18px;
}
.hero-visual figcaption { font-size: 12px; color: var(--ink-faint); text-align: center; margin-top: 8px; }

/* ---------- pain points ---------- */
.pain-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 18px; }
.pain {
  background: var(--bg); border: 1px solid var(--line); border-radius: var(--radius);
  padding: 22px;
}
.pain .num { font-size: 13px; font-weight: 700; color: var(--primary); letter-spacing: 1px; }
.pain h3 { margin: 6px 0 8px; font-size: 17px; }
.pain p { margin: 0; font-size: 14.5px; color: var(--ink-soft); }

/* ---------- features ---------- */
.feature {
  display: grid; grid-template-columns: 340px 1fr; gap: 30px;
  padding: 30px 0; border-bottom: 1px solid var(--line);
}
.feature:last-child { border-bottom: none; padding-bottom: 4px; }
.feature .text h3 { margin: 2px 0 10px; font-size: 19px; }
.feature .text p { margin: 0 0 10px; font-size: 15px; color: var(--ink-soft); }
.feature ul { margin: 0; padding-left: 20px; font-size: 14.5px; color: var(--ink-soft); }
.feature ul li { margin: 4px 0; }
.feature .status-note { font-size: 13px; color: var(--ink-faint); margin-top: 12px; }

.screenshot {
  position: relative; background: var(--bg); border: 1px solid var(--line);
  border-radius: var(--radius); overflow: hidden; min-height: 200px;
  display: flex; align-items: center; justify-content: center;
}
.screenshot img { display: block; width: 100%; height: auto; }
.screenshot .ph {
  text-align: center; padding: 40px 18px; color: var(--ink-faint);
}
.screenshot .ph .frame {
  width: 74px; height: 56px; margin: 0 auto 12px;
  border: 1.5px dashed #b9c3d4; border-radius: 8px;
  display: flex; align-items: center; justify-content: center;
  font-size: 24px; color: #b9c3d4;
}
.screenshot .ph .fname { font-family: ui-monospace, SFMono-Regular, Menlo, monospace; font-size: 12px; }

/* ---------- architecture ---------- */
.arch-diagram { margin: 0 0 26px; }
.arch-diagram svg { width: 100%; height: auto; display: block; }
table.info {
  width: 100%; border-collapse: collapse; background: var(--card);
  border: 1px solid var(--line); border-radius: var(--radius); overflow: hidden;
  font-size: 14.5px;
}
table.info th, table.info td {
  padding: 12px 16px; text-align: left; border-bottom: 1px solid var(--line); vertical-align: top;
}
table.info th { background: #f0f4fa; font-size: 13.5px; white-space: nowrap; }
table.info tr:last-child td { border-bottom: none; }
table.info td.wide { min-width: 180px; }
code {
  font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  font-size: 0.9em; background: #eef1f7; border-radius: 4px; padding: 1px 6px; color: #24446e;
}

/* ---------- demo / radar ---------- */
.snapshot-note {
  background: var(--primary-soft); border: 1px solid #c9d8f8; color: #24446e;
  border-radius: var(--radius); padding: 12px 18px; font-size: 14px; margin-bottom: 24px;
}
.radar-layout { display: grid; grid-template-columns: 1.05fr 1fr; gap: 26px; align-items: start; }
#radar-chart { width: 100%; height: 430px; background: var(--card); border: 1px solid var(--line); border-radius: var(--radius); }
.radar-side { background: var(--card); border: 1px solid var(--line); border-radius: var(--radius); padding: 18px 20px; }
.radar-side h3 { margin: 0 0 6px; font-size: 16px; }
.radar-side .meta { font-size: 13px; color: var(--ink-faint); margin-bottom: 14px; }
.legend { display: flex; flex-wrap: wrap; gap: 14px; font-size: 13px; color: var(--ink-soft); margin-bottom: 10px; }
.legend .item { display: inline-flex; align-items: center; gap: 6px; }
.legend .swatch { width: 12px; height: 12px; border-radius: 3px; display: inline-block; }

.blind-list { margin-top: 26px; }
table.blind { width: 100%; border-collapse: collapse; background: var(--card); border: 1px solid var(--line); border-radius: var(--radius); overflow: hidden; font-size: 14.5px; }
table.blind th, table.blind td { padding: 11px 14px; text-align: left; border-bottom: 1px solid var(--line); }
table.blind th { background: #f0f4fa; font-size: 13px; white-space: nowrap; }
table.blind tr.row-main { cursor: pointer; }
table.blind tr.row-main:hover { background: #f7f9fd; }
table.blind tr.row-main.open { background: #f0f4fa; }
table.blind tr.row-detail > td { padding: 0; border-bottom: 1px solid var(--line); }

/* mobile: one card per topic instead of the table */
.blind-cards { display: none; }
.blind-card {
  background: var(--card); border: 1px solid var(--line); border-radius: var(--radius);
  margin-bottom: 12px; overflow: hidden;
}
.blind-card .bc-head { display: flex; align-items: center; gap: 10px; padding: 13px 16px; cursor: pointer; }
.blind-card .bc-head:hover { background: #f7f9fd; }
.blind-card .bc-name { font-weight: 600; font-size: 15px; flex: 1; }
.blind-card .bc-stats {
  display: grid; grid-template-columns: repeat(3, 1fr); gap: 8px;
  padding: 0 16px 13px; font-size: 12.5px; color: var(--ink-faint);
}
.blind-card .bc-stats b { display: block; font-size: 15px; color: var(--ink); font-weight: 700; }
.blind-card .detail-box { border-top: 1px solid var(--line); }

@media (max-width: 700px) {
  .blind-table-wrap { display: none; }
  .blind-cards { display: block; }
}

/* term list inside detail */
.term-list { margin: 6px 0 0; padding: 0; list-style: none; font-size: 13.5px; }
.term-list li { padding: 7px 0; border-bottom: 1px dashed #e3e8f0; }
.term-list li:last-child { border-bottom: none; }
.term-line { display: flex; align-items: baseline; gap: 8px; flex-wrap: wrap; }
.term-name { font-weight: 600; }
.term-alias { color: var(--ink-faint); font-size: 12.5px; }
.term-found { color: var(--ok); font-weight: 600; white-space: nowrap; }
.term-miss { color: var(--bad); font-weight: 600; white-space: nowrap; }
.term-chunks { margin-top: 4px; color: var(--ink-soft); font-size: 12.5px; }
.term-chunks div { padding: 1px 0; }

/* question content with expand */
.q-item { padding: 8px 0; border-bottom: 1px dashed #e3e8f0; font-size: 13.5px; }
.q-item:last-child { border-bottom: none; }
.q-item .q-line { color: var(--ink-soft); }
.q-item .q-content { margin-top: 4px; color: var(--ink-soft); }
.q-item .q-toggle {
  background: none; border: none; color: var(--primary); font-size: 12.5px;
  padding: 0; cursor: pointer; text-decoration: underline;
}
.detail-box { padding: 18px 18px 20px; background: #fafbfd; }
.detail-box h4 { margin: 0 0 10px; font-size: 14px; color: var(--ink-soft); }
.evidence {
  background: #fff; border: 1px solid var(--line); border-left: 3px solid var(--primary);
  border-radius: 8px; padding: 12px 16px; font-size: 14px;
}
.evidence .ev-meta { font-size: 12.5px; color: var(--ink-faint); margin-top: 8px; }
.evidence .ev-content { color: var(--ink-soft); font-size: 13.5px; }
.q-list { margin: 14px 0 0; padding: 0; list-style: none; font-size: 13.5px; color: var(--ink-soft); }
.q-list li { padding: 3px 0; }
.reason-text { font-size: 13.5px; color: var(--ink-soft); margin: 12px 0 0; }
.muted { color: var(--ink-faint); }

.badge {
  display: inline-block; padding: 2px 10px; border-radius: 999px; font-size: 12.5px; font-weight: 600; white-space: nowrap;
}
.badge.covered { background: var(--ok-soft); color: var(--ok); }
.badge.thin { background: var(--warn-soft); color: var(--warn); }
.badge.missing { background: var(--bad-soft); color: var(--bad); }
.badge.unknown { background: #eef1f7; color: var(--ink-faint); }

/* ---------- run locally ---------- */
.cmd-block {
  background: #101a2e; color: #d5e2f7; border-radius: var(--radius);
  padding: 18px 22px; font-family: ui-monospace, SFMono-Regular, Menlo, monospace;
  font-size: 14px; line-height: 2; overflow-x: auto; margin: 18px 0 10px;
}
.cmd-block .cmt { color: #6f81a3; }
.cmd-links { font-size: 14px; }
.table-scroll { overflow-x: auto; -webkit-overflow-scrolling: touch; }
.cmd-links a { color: var(--primary); text-decoration: none; margin-right: 18px; }
.cmd-links a:hover { text-decoration: underline; }

/* ---------- video ---------- */
.video-box {
  background: var(--card); border: 1px solid var(--line); border-radius: var(--radius);
  overflow: hidden;
}
.video-box video { display: block; width: 100%; max-height: 560px; background: #000; }
.video-pending {
  padding: 90px 20px; text-align: center; color: var(--ink-faint);
}
.video-pending .film { font-size: 40px; margin-bottom: 10px; }

/* ---------- sessions ---------- */
.sessions-table-wrap { overflow-x: auto; }
table.sessions { width: 100%; border-collapse: collapse; background: var(--card); border: 1px solid var(--line); border-radius: var(--radius); overflow: hidden; font-size: 14px; }
table.sessions { table-layout: fixed; }
table.sessions th, table.sessions td { padding: 10px 14px; text-align: left; border-bottom: 1px solid var(--line); white-space: nowrap; }
table.sessions th { background: #f0f4fa; font-size: 13px; }
table.sessions td.title-cell { white-space: normal; overflow-wrap: anywhere; }
table.sessions td.num, table.sessions th.num { text-align: right; white-space: nowrap; }
table.sessions tr.total td { background: #f0f4fa; font-weight: 700; border-bottom: none; }
table.sessions td.title-cell { min-width: 260px; }
.model-tag { white-space: nowrap; }
.model-tag.glm { color: #9333ea; font-weight: 600; }

.split-note {
  display: grid; grid-template-columns: 1fr 1fr; gap: 18px; margin: 26px 0 18px;
}
.split-card { background: var(--card); border: 1px solid var(--line); border-radius: var(--radius); padding: 20px 22px; }
.split-card h3 { margin: 0 0 8px; font-size: 16px; }
.split-card ul { margin: 0; padding-left: 18px; font-size: 14px; color: var(--ink-soft); }
.split-card ul li { margin: 4px 0; }

/* ---------- usage ---------- */
.usage-card {
  background: var(--card); border: 1px dashed #b9c3d4; border-radius: var(--radius);
  padding: 48px 30px; text-align: center; color: var(--ink-soft);
}
.usage-card .icon { font-size: 34px; margin-bottom: 10px; }
.usage-stats { display: grid; grid-template-columns: repeat(4, 1fr); gap: 16px; margin-bottom: 20px; }
.stat { background: var(--card); border: 1px solid var(--line); border-radius: var(--radius); padding: 18px; text-align: center; }
.stat .v { font-size: 26px; font-weight: 700; color: var(--ink); }
.stat .k { font-size: 13px; color: var(--ink-faint); margin-top: 4px; }
.usage-src { font-size: 13px; color: var(--ink-faint); }

.usage-block {
  background: var(--card); border: 1px solid var(--line); border-radius: var(--radius);
  padding: 22px 24px; margin-bottom: 18px;
}
.usage-block h3 { margin: 0 0 14px; font-size: 16px; }
.usage-block .usage-stats { margin-bottom: 6px; }
.feedback-list { margin: 0; padding: 0; list-style: none; }
.feedback-list li {
  border-left: 3px solid var(--primary); background: #f7f9fd;
  border-radius: 0 8px 8px 0; padding: 12px 16px; margin-bottom: 10px;
  font-size: 14.5px; color: var(--ink-soft); font-style: normal;
}
.feedback-list li:last-child { margin-bottom: 0; }

/* ---------- footer ---------- */
footer {
  background: #101a2e; color: #aab8d0; padding: 44px 0 36px; font-size: 13.5px;
}
footer .cols { display: grid; grid-template-columns: 1.4fr 1fr 1fr; gap: 30px; }
footer h4 { color: #fff; font-size: 14px; margin: 0 0 10px; }
footer a { color: #8fb1f5; text-decoration: none; }
footer a:hover { text-decoration: underline; }
footer p { margin: 4px 0; }
footer .copy { border-top: 1px solid #26324d; margin-top: 28px; padding-top: 18px; color: #7787a5; font-size: 12.5px; }

/* ---------- responsive ---------- */
@media (max-width: 900px) {
  .hero-grid, .radar-layout, .feature, .split-note { grid-template-columns: 1fr; }
  .feature .shot { order: 2; }
  .pain-grid { grid-template-columns: 1fr; }
  .usage-stats { grid-template-columns: repeat(2, 1fr); }
  footer .cols { grid-template-columns: 1fr; gap: 20px; }
  nav.topbar .links { display: none; }
}
@media (max-width: 480px) {
  .hero h1 { font-size: 30px; }
  section { padding: 40px 0; }
  #radar-chart { height: 340px; }
}

